import React, { useEffect, useState } from 'react';
import { Card, CardHeader, Table, Btn, Badge, Modal, FormRow, FormField, Spinner } from '../components/ui/Card';
import api from '../utils/api';
import toast from 'react-hot-toast';
import { useAuth } from '../contexts/AuthContext';

const TYPES_ABSENCE = ['Congé annuel', 'Congé maladie', 'Congé maternité/paternité', 'Congé sans solde', 'Permission spéciale'];

export default function AbsencesPage() {
  const { hasRole, user } = useAuth();
  const [absences, setAbsences] = useState([]);
  const [personnel, setPersonnel] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [form, setForm] = useState({ personnel_id: '', type: 'Congé annuel', date_debut: '', date_fin: '', motif: '' });
  const [saving, setSaving] = useState(false);
  const [filterStatut, setFilterStatut] = useState('');

  const canApprove = hasRole('super_admin', 'assistant_admin', 'direction');

  useEffect(() => {
    document.getElementById('page-title') && (document.getElementById('page-title').textContent = 'Absences & Congés');
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [a, p] = await Promise.all([api.get('/absences'), api.get('/personnel')]);
      setAbsences(a.data.data);
      setPersonnel(p.data.data);
    } catch { toast.error('Erreur de chargement'); }
    finally { setLoading(false); }
  };

  const filtered = filterStatut ? absences.filter(a => a.statut === filterStatut) : absences;

  const handleCreate = async (e) => {
    e.preventDefault(); setSaving(true);
    try {
      await api.post('/absences', form);
      toast.success('Demande d\'absence créée');
      setModalOpen(false);
      loadData();
    } catch (err) { toast.error(err.response?.data?.message || 'Erreur'); }
    finally { setSaving(false); }
  };

  const handleValidate = async (id, statut) => {
    try {
      await api.put(`/absences/${id}`, { statut });
      toast.success(`Demande ${statut}`);
      loadData();
    } catch { toast.error('Erreur'); }
  };

  const statsBadge = (statut) => {
    const m = { 'en_attente': 'warning', 'approuvé': 'success', 'refusé': 'error' };
    return <Badge type={m[statut] || 'default'}>{statut}</Badge>;
  };

  const columns = [
    { key: 'personnel_nom', header: 'Personnel' },
    { key: 'type', header: 'Type', render: v => <Badge type="info">{v}</Badge> },
    { key: 'date_debut', header: 'Début', render: v => v ? new Date(v).toLocaleDateString('fr-FR') : '—' },
    { key: 'date_fin', header: 'Fin', render: v => v ? new Date(v).toLocaleDateString('fr-FR') : '—' },
    { key: 'motif', header: 'Motif', render: v => <span style={{ fontSize: '0.83rem', color: 'var(--gray-600)' }}>{v || '—'}</span> },
    { key: 'statut', header: 'Statut', render: v => statsBadge(v) },
    { key: 'actions', header: 'Actions', render: (_, row) => (
      <div style={{ display: 'flex', gap: 6 }}>
        {canApprove && row.statut === 'en_attente' && (
          <>
            <Btn size="sm" variant="success" onClick={() => handleValidate(row.id, 'approuvé')}>✅ Approuver</Btn>
            <Btn size="sm" variant="danger" onClick={() => handleValidate(row.id, 'refusé')}>❌ Refuser</Btn>
          </>
        )}
      </div>
    )}
  ];

  const stats = { total: absences.length, en_attente: absences.filter(a => a.statut === 'en_attente').length, approuves: absences.filter(a => a.statut === 'approuvé').length, refuses: absences.filter(a => a.statut === 'refusé').length };

  return (
    <div className="animate-fade">
      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 20 }}>
        {[
          { label: 'Total', value: stats.total, color: 'var(--navy)' },
          { label: 'En attente', value: stats.en_attente, color: 'var(--orange)' },
          { label: 'Approuvés', value: stats.approuves, color: 'var(--emerald)' },
          { label: 'Refusés', value: stats.refuses, color: 'var(--red)' },
        ].map(s => (
          <div key={s.label} style={{ background: 'white', borderRadius: 'var(--radius)', boxShadow: 'var(--shadow)', padding: '18px 20px', borderLeft: `4px solid ${s.color}` }}>
            <p style={{ fontSize: '0.75rem', color: 'var(--gray-500)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 4 }}>{s.label}</p>
            <p style={{ fontSize: '2rem', fontWeight: 700, color: s.color, lineHeight: 1 }}>{s.value}</p>
          </div>
        ))}
      </div>

      <Card>
        <CardHeader
          title="Absences & Congés"
          subtitle="Gestion des demandes d'absence"
          action={
            <div style={{ display: 'flex', gap: 10 }}>
              <select value={filterStatut} onChange={e => setFilterStatut(e.target.value)} style={{ width: 'auto' }}>
                <option value="">Tous les statuts</option>
                <option value="en_attente">En attente</option>
                <option value="approuvé">Approuvés</option>
                <option value="refusé">Refusés</option>
              </select>
              <Btn variant="gold" onClick={() => setModalOpen(true)}>➕ Nouvelle demande</Btn>
            </div>
          }
        />
        {loading ? <Spinner /> : <Table columns={columns} data={filtered} emptyMessage="Aucune demande d'absence" />}
      </Card>

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title="Nouvelle demande d'absence">
        <form onSubmit={handleCreate} style={{ padding: 24 }}>
          <FormRow cols={1}>
            <FormField label="Personnel" required>
              <select value={form.personnel_id} onChange={e => setForm({...form, personnel_id: e.target.value})} required>
                <option value="">— Sélectionner —</option>
                {personnel.map(p => <option key={p.id} value={p.id}>{p.prenom} {p.nom} — {p.poste}</option>)}
              </select>
            </FormField>
          </FormRow>
          <FormRow cols={1}>
            <FormField label="Type d'absence">
              <select value={form.type} onChange={e => setForm({...form, type: e.target.value})}>
                {TYPES_ABSENCE.map(t => <option key={t}>{t}</option>)}
              </select>
            </FormField>
          </FormRow>
          <FormRow>
            <FormField label="Date de début" required><input type="date" value={form.date_debut} onChange={e => setForm({...form, date_debut: e.target.value})} required /></FormField>
            <FormField label="Date de fin" required><input type="date" value={form.date_fin} onChange={e => setForm({...form, date_fin: e.target.value})} required /></FormField>
          </FormRow>
          <FormRow cols={1}>
            <FormField label="Motif"><textarea value={form.motif} onChange={e => setForm({...form, motif: e.target.value})} rows={3} style={{ resize: 'vertical' }} /></FormField>
          </FormRow>
          <div style={{ display: 'flex', gap: 12, justifyContent: 'flex-end' }}>
            <Btn type="button" variant="secondary" onClick={() => setModalOpen(false)}>Annuler</Btn>
            <Btn type="submit" variant="gold" disabled={saving}>{saving ? 'Envoi...' : '📤 Soumettre la demande'}</Btn>
          </div>
        </form>
      </Modal>
    </div>
  );
}
